/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Determinant, Matrix, MatrixPermute, MatrixSymbol, OneMatrix, Perm, PermutationMatrix, Sym, ZeroMatrix, isUnsolved, rational, rewrite, unchanged } from '../../../src';
import { sympyMatches, sympyStr } from '../../sympy-str';

describe("doctests of sympy.matrices.expressions.permutation", () => {
  it("B.as_explicit()", () => {
    expect(sympyStr(MatrixPermute(Matrix.of([[rational(1), rational(2), rational(3)], [rational(4), rational(5), rational(6)], [rational(7), rational(8), rational(9)]]), new Perm([1, 2, 0]), rational(0)).asExplicit())).toBe('Matrix([[4, 5, 6], [7, 8, 9], [1, 2, 3]])');
  });
  it("B.as_explicit() (2)", () => {
    expect(sympyStr(MatrixPermute(Matrix.of([[rational(1), rational(2), rational(3)], [rational(4), rational(5), rational(6)], [rational(7), rational(8), rational(9)]]), new Perm([1, 2, 0]), rational(1)).asExplicit())).toBe('Matrix([[2, 3, 1], [5, 6, 4], [8, 9, 7]])');
  });
  it("Matrix(P*M)", () => {
    expect(sympyStr(Matrix.of([[rational(1)], [rational(2)], [rational(0)]]))).toBe('Matrix([[1], [2], [0]])');
  });
  it("Matrix(M.T*P)", () => {
    expect(sympyStr(Matrix.of([[rational(2), rational(0), rational(1)]]))).toBe('Matrix([[2, 0, 1]])');
  });
  it("P", () => {
    expect(sympyStr(PermutationMatrix(new Perm([1, 2, 0])).asExplicit())).toBe('Matrix([[0, 1, 0], [0, 0, 1], [1, 0, 0]])');
  });
});

